-- A target-less `ON CONFLICT DO NOTHING` arbitrates before the row enters any index: a
-- conflict on the unique `b` skips the row, whatever an earlier index would say of `a`.
-- @setup
CREATE TABLE t (a text, b int);
CREATE INDEX t_a ON t (a);
CREATE UNIQUE INDEX t_b ON t (b);
INSERT INTO t VALUES ('x', 1);
-- @test
INSERT INTO t VALUES ('', 1) ON CONFLICT DO NOTHING RETURNING b;
